const input = $input.first().json.body || $input.first().json;

return [{
  json: {
    theme: input.theme || 'Fantasy',
    genre: input.genre || 'Adventure',
    target_platform: input.target_platform || 'TikTok',
    story_length: input.story_length || 'short',
    num_episodes: input.num_episodes || 2,
    num_scenes_per_episode: input.num_scenes_per_episode || 3
  }
}];

const response = $input.first().json;
const raw = response.choices?.[0]?.message?.content || '';

let story;
try {
  story = JSON.parse(raw.replace(/```json/gi, '').replace(/```/g, '').trim());
} catch (e) {
  throw new Error('Geçersiz JSON: ' + raw.substring(0, 200));
}

if (!story.episodes) throw new Error('Episodes bulunamadı');

return [{ json: story }];

const story = $input.first().json;
const allScenes = [];

story.episodes.forEach(ep => {
  ep.scenes?.forEach(sc => {
    allScenes.push({
      story_title: story.title,
      story_genre: story.genre,
      story_theme: story.theme,
      characters: story.characters,
      episode_number: ep.episode_number,
      episode_title: ep.title,
      scene_number: sc.scene_number,
      description: sc.description,
      dialogue_speaker: sc.dialogue?.speaker || '',
      dialogue_text: sc.dialogue?.text || '',
      asset_key: `ep${ep.episode_number}_sc${sc.scene_number}`
    });
  });
});

return allScenes.map(s => ({ json: s }));

const scene = $input.first().json;
const chars = scene.characters || [];
const speaker = chars.find(c => c.name === scene.dialogue_speaker);

const genreStyle = {
  'Fantasy': 'fantasy art, magical lighting, ethereal',
  'Sci-Fi': 'sci-fi, cyberpunk, neon lights, futuristic',
  'Horror': 'dark gothic, dramatic shadows, ominous',
  'Romance': 'soft warm lighting, pastel colors, dreamy',
  'Adventure': 'epic cinematic, vivid colors, dynamic',
  'Drama': 'realistic, natural lighting, emotional'
};

const platform = {
  'TikTok': 'vertical 9:16, close-up',
  'Shorts': 'vertical 9:16, dynamic angle',
  'Reels': 'vertical 9:16, cinematic'
};

const prompt = [
  scene.description,
  speaker?.appearance || '',
  genreStyle[scene.story_genre] || 'cinematic',
  platform[scene.target_platform] || 'vertical 9:16',
  'ultra detailed, 4K, film grain'
].filter(Boolean).join(', ');

return [{ json: { ...scene, image_prompt: prompt } }];

const response = $input.first().json;
const scene = $('5. Image Prompt Oluştur').first().json;

let imageData = null;
if (Array.isArray(response) && response[0]) {
  imageData = response[0].image || response[0].base64;
} else if (response.image) {
  imageData = response.image;
}

if (!imageData) throw new Error('Görsel bulunamadı');

const base64 = imageData.startsWith('data:') ? imageData : `data:image/png;base64,${imageData}`;

return [{ json: { ...scene, image_base64: base64 } }];

const scene = $input.first().json;
const b64 = scene.image_base64.replace(/^data:image\/\w+;base64,/, '');
const imageBytes = Buffer.from(b64, 'base64');

// Canvas benzeri işlem - n8n'da PIL yok ama base64 manipulation yapabiliriz
// Bu kısım gerçek bir Python subprocess gerektirir
// Şimdilik orijinal görseli döndürüyoruz

return [{
  json: {
    ...scene,
    bubble_text: scene.dialogue_text,
    speaker_name: scene.dialogue_speaker,
    processed_image: scene.image_base64,
    has_bubble: Boolean(scene.dialogue_text)
  }
}];

const voiceBinary = $input.first().binary;
const scene = $('8. Bubble Hazırla').first().json;

const voiceBase64 = voiceBinary?.data?.data
  ? Buffer.from(voiceBinary.data.data).toString('base64')
  : null;

return [{
  json: {
    asset_key: scene.asset_key,
    episode_number: scene.episode_number,
    episode_title: scene.episode_title,
    scene_number: scene.scene_number,
    description: scene.description,
    dialogue_speaker: scene.dialogue_speaker,
    dialogue_text: scene.dialogue_text,
    image_url: scene.processed_image,
    voice_base64: voiceBase64 ? `data:audio/mp3;base64,${voiceBase64}` : null,
    status: 'scene_complete'
  }
}];

const allScenes = $input.all().map(i => i.json);

const episodes = {};
allScenes.forEach(sc => {
  if (!episodes[sc.episode_number]) {
    episodes[sc.episode_number] = { episode_number: sc.episode_number, episode_title: sc.episode_title, scenes: [] };
  }
  episodes[sc.episode_number].scenes.push(sc);
});

Object.values(episodes).forEach(ep => ep.scenes.sort((a, b) => a.scene_number - b.scene_number));

const sorted = Object.values(episodes).sort((a, b) => a.episode_number - b.episode_number);

return [{
  json: {
    story_title: allScenes[0]?.story_title || 'Untitled',
    total_scenes: allScenes.length,
    episodes: sorted,
    all_scenes: allScenes,
    status: 'ready_for_video'
  }
}];

// FFmpeg command to create video from images and audio
// Bu kısım Execute Command node ile çalıştırılabilir
// Örnek: ffmpeg -loop 1 -i image.jpg -i audio.mp3 -c:v libx264 -c:a aac -shortest output.mp4

const data = $input.first().json;

// Sahneleri base64 olarak video service'e gönder
// Gerçek implementasyon için harici video servis gerekir
// Şimdilik sahne bilgilerini döndür

return [{
  json: {
    ...data,
    video_generated: false,
    note: 'Video oluşturma için FFmpeg veya harici servis gerekli',
    scenes_data: data.all_scenes.map(sc => ({
      asset_key: sc.asset_key,
      image: sc.image_url,
      audio: sc.voice_base64,
      duration: 5
    }))
  }
}];
